  return SweepRun(
    res.stdout.toString(),
    File('${dir.path}/log').readAsLinesSync(),
    File('${dir.path}/last-body.md').existsSync()
        ? File('${dir.path}/last-body.md').readAsStringSync()
        : null,
  );
}

